      const w = S.cur;
      if (w.length < LEN) { flash('Not enough letters'); shake(); return; }
      if (!ALLOWED.has(w)) { flash('Not in word list'); shake(); return; }
      if (S.hard) { const err = hardCheck(w, S.guesses); if (err) { flash(err); shake(); return; } }
